-- Weekly Arena 2026-W52: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W52', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-12-21T00:00:00.000Z', '2026-12-28T00:00:00.000Z', 60, 'published', $WK7cbd8b5ee321$[{"id":"wk-2026-w52-01-9ac5","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $19$ and $9$ and each non-parallel side has length $13$. Find its area.","type":"text","correctAnswer":"168","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $5$ and hypotenuse $13$.","solution":"The height is $\\sqrt{13^2-5^2}=12$, so the area is $\\tfrac12(19+9)(12)=168$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w52-02-c0e7","title":"Sum of Divisors","topic":"Number Theory","level":"Foundation","question":"Find the sum of all positive divisors of $3500$.","type":"text","correctAnswer":"8736","hint":"Factor $N$ into primes; the divisor sum is multiplicative.","solution":"$3500=7^{1}\\cdot 5^{3}\\cdot 2^{2}$, so the divisor sum is $8736$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w52-03-0720","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 3 \\pmod{9}$, $n\\equiv 4 \\pmod{5}$, $n\\equiv 6 \\pmod{11}$.","type":"text","correctAnswer":"39","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $39$ modulo $495$, and $39$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w52-04-4727","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $588$ that are divisible by $11$ or by $12$ (or both).","type":"text","correctAnswer":"29121","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $11$, $12$ and $132$ gives $29121$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w52-05-256e","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(5,7)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(4,4)$?","type":"text","correctAnswer":"512","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{12}{5}-\\binom{8}{4}\\binom{4}{1}=512$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w52-06-ce18","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 5$. Find $x^{5} + \\dfrac{1}{x^{5}}$.","type":"text","correctAnswer":"2525","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=5T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=5$ the recurrence gives $T_{5}=2525$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w52-07-b60d","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $17$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"442","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=17$, i.e. $442$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w52-08-3aff","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 6t + 3 = 0$. Find the remainder when $r^{6} + s^{6}$ is divided by $1000$.","type":"text","correctAnswer":"190","hint":"Let $S_k=r^k+s^k$. Then $S_k=6S_{k-1}-3S_{k-2}$, with $S_0=2$, $S_1=6$.","solution":"Using $S_k=6S_{k-1}-3S_{k-2}$ from $S_0=2$, $S_1=6$ gives $S_{6}=26190$, whose remainder modulo $1000$ is $190$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w52-09-16b5","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 3-tuples $(x_1,\\dots,x_3)$ of non-negative integers satisfy $x_1+\\cdots+x_3=11$ with every $x_i\\le 8$?","type":"text","correctAnswer":"60","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $60$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2026-w52-10-8282","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(6,13)$ and $(5,8)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"8","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $17$ and the boundary has $B=3$ lattice points, so $I=(17-3+2)/2=8$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK7cbd8b5ee321$::jsonb
